"""Expand repeating room-booking rules into concrete UTC occurrences."""

from __future__ import annotations

import calendar
from datetime import date, datetime, timedelta

__all__ = ["expand"]

# Monday == 0 ... Sunday == 6, the same numbering as date.weekday().
_WEEKDAYS = ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
_WEEKDAY_INDEX = {name: index for index, name in enumerate(_WEEKDAYS)}

_LOCAL_FORMAT = "%Y-%m-%dT%H:%M"
_UTC_FORMAT = "%Y-%m-%dT%H:%MZ"
_VALID_FREQUENCIES = ("daily", "weekly", "monthly", "yearly")


def _parse_local(text: str) -> datetime:
    return datetime.strptime(text, _LOCAL_FORMAT)


def _parse_utc(text: str) -> datetime:
    return datetime.strptime(text, _UTC_FORMAT)


def _days_in_month(year: int, month: int) -> int:
    return calendar.monthrange(year, month)[1]


# ---------------------------------------------------------------- date patterns
#
# Each generator yields the *local* dates of a rule in ascending order,
# starting at `lower` (inclusive) and never going past `upper` (inclusive).
# Nothing before the start date is ever yielded: nothing happens before start.
#
# `lower` lets a call jump straight to the requested window instead of
# replaying decades of history, and `upper` keeps every iteration finite even
# when a pattern is empty for a long stretch (31st of February, 5th Friday,
# 29 February in years that are not leap years ...).


def _month_days(year: int, month: int, spec: tuple) -> list[int]:
    """Sorted, de-duplicated days of (year, month) selected by `spec`."""
    kind = spec[0]
    if kind == "days":
        last = _days_in_month(year, month)
        days = set()
        for value in spec[1]:
            day = value if value > 0 else last + value + 1
            if 1 <= day <= last:
                days.add(day)
        return sorted(days)
    if kind == "nth":
        nth, weekday = spec[1], spec[2]
        first = date(year, month, 1)
        current = first + timedelta(days=(weekday - first.weekday()) % 7)
        matches = []
        while current.month == month:
            matches.append(current.day)
            current += timedelta(days=7)
        index = nth - 1 if nth > 0 else nth
        if -len(matches) <= index < len(matches):
            return [matches[index]]
        return []
    # default: the day of month of the start date
    day = spec[1]
    return [day] if day <= _days_in_month(year, month) else []


def _daily_dates(start_date, interval, lower, upper):
    if lower < start_date:
        lower = start_date
    delta = (lower - start_date).days
    step = -(-delta // interval)                       # ceil(delta / interval)
    current = start_date + timedelta(days=step * interval)
    while current <= upper:
        yield current
        current += timedelta(days=interval)


def _weekly_dates(start_date, interval, weekdays, lower, upper):
    first_monday = start_date - timedelta(days=start_date.weekday())
    lower_monday = lower - timedelta(days=lower.weekday())
    relative = (lower_monday - first_monday).days // 7  # week 0 contains start
    if relative < 0:
        relative = 0
    week = -(-relative // interval) * interval          # first counted week
    while True:
        monday = first_monday + timedelta(days=7 * week)
        if monday > upper:
            return
        for weekday in weekdays:                        # ascending inside a week
            day = monday + timedelta(days=weekday)
            if day > upper:
                break
            if day < start_date or day < lower:         # week 0: on/after start
                continue
            yield day
        week += interval


def _monthly_dates(start_date, interval, spec, lower, upper):
    first_month = start_date.year * 12 + (start_date.month - 1)
    lower_month = lower.year * 12 + (lower.month - 1)
    upper_month = upper.year * 12 + (upper.month - 1)
    relative = lower_month - first_month                # month 0 contains start
    if relative < 0:
        relative = 0
    month = -(-relative // interval) * interval         # first counted month
    while True:
        absolute = first_month + month
        if absolute > upper_month:
            return
        year, mon = divmod(absolute, 12)
        mon += 1
        for day_number in _month_days(year, mon, spec):  # sorted, valid only
            day = date(year, mon, day_number)
            if day > upper:
                break
            if day < start_date or day < lower:         # nothing before start
                continue
            yield day
        month += interval


def _yearly_dates(start_date, interval, lower, upper):
    year = start_date.year
    if lower.year > year:
        relative = lower.year - year
        year += -(-relative // interval) * interval     # first counted year
    while year <= upper.year:
        try:
            day = date(year, start_date.month, start_date.day)
        except ValueError:                              # 29 February, no leap
            day = None
        if day is not None and day >= lower and day >= start_date:
            yield day
        year += interval


# -------------------------------------------------------------------- expander


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    freq = rule.get("freq")
    if freq not in _VALID_FREQUENCIES:
        raise ValueError("unknown freq: %r" % (freq,))
    interval = rule.get("interval", 1)
    if interval < 1:
        raise ValueError("interval must be >= 1, got %r" % (interval,))
    count = rule.get("count")
    until_text = rule.get("until")
    if count is not None and until_text is not None:
        raise ValueError("'count' and 'until' are mutually exclusive")
    month_day = rule.get("by_month_day")
    nth_weekday = rule.get("by_nth_weekday")
    if month_day is not None and nth_weekday is not None:
        raise ValueError("'by_month_day' and 'by_nth_weekday' are mutually exclusive")

    start = _parse_local(rule["start"])
    start_date = start.date()
    start_hour, start_minute = start.hour, start.minute
    offset = int(rule["utc_offset_minutes"])
    shift = timedelta(minutes=offset)                   # local = utc + shift

    # Everything below is done in local wall time; the window moves with it.
    window_from = _parse_utc(window_start) + shift
    window_to = _parse_utc(window_end) + shift
    end = window_to                                     # exclusive
    if until_text is not None:
        until_end = _parse_local(until_text) + timedelta(minutes=1)
        if until_end < end:
            end = until_end
    if window_from >= end:
        return []

    # Rules with "count" must be replayed from the beginning; the others jump
    # straight to the first date that can possibly belong to the window.
    lower = start_date if count is not None else window_from.date()
    if lower < start_date:
        lower = start_date
    upper = end.date()
    if lower > upper:
        return []

    if freq == "daily":
        dates = _daily_dates(start_date, interval, lower, upper)
    elif freq == "weekly":
        if rule.get("by_weekday"):
            names = rule["by_weekday"]
        else:
            names = (_WEEKDAYS[start_date.weekday()],)
        weekdays = tuple(sorted({_WEEKDAY_INDEX[name] for name in names}))
        dates = _weekly_dates(start_date, interval, weekdays, lower, upper)
    elif freq == "monthly":
        if month_day is not None:
            spec = ("days", tuple(month_day))
        elif nth_weekday is not None:
            spec = ("nth", nth_weekday[0], _WEEKDAY_INDEX[nth_weekday[1]])
        else:
            spec = ("dom", start_date.day)
        dates = _monthly_dates(start_date, interval, spec, lower, upper)
    else:
        dates = _yearly_dates(start_date, interval, lower, upper)

    excluded = set()
    for text in rule.get("exclude") or ():
        excluded.add(_parse_local(text))

    results: list[datetime] = []
    if count is not None:
        seen = 0
        for day in dates:
            moment = datetime(day.year, day.month, day.day, start_hour, start_minute)
            if moment >= end:
                break
            seen += 1                                   # exclusions still count
            if seen > count:
                break
            if moment < window_from or moment in excluded:
                continue
            results.append(moment - shift)               # local -> utc
    else:
        for day in dates:
            moment = datetime(day.year, day.month, day.day, start_hour, start_minute)
            if moment >= end:
                break
            if moment < window_from or moment in excluded:
                continue
            results.append(moment - shift)               # local -> utc

    return [item.strftime(_UTC_FORMAT) for item in results]
